function card(v,i,likes){const p=v.profiles||{},url=safeUrl(v.video_url),poster=safeUrl(v.thumbnail_url),yt=youtubeId(url),file=/\.(mp4|webm|mov)(\?|$)/i.test(url)||v.platform==="upload",isSaved=saved().has(v.id),media=yt?`<button class="youtube-preview" data-youtube-play="${esc(yt)}" type="button" aria-label="Reproducir ${esc(v.title||"video de YouTube")}"><img src="https://i.ytimg.com/vi/${encodeURIComponent(yt)}/hqdefault.jpg" alt="" loading="eager"><i>▶</i><span>TOCÁ PARA REPRODUCIR</span></button>`:file&&url?`<video src="${esc(url)}" ${poster?`poster="${esc(poster)}"`:""} playsinline loop preload="metadata"></video>`:poster?`<img src="${esc(poster)}" alt="" loading="lazy">`:`<div class="video-placeholder"><b>LS8</b><span>${url?"Tocá para abrir":"Sin vista previa"}</span></div>`;return `<article class="video-card" data-id="${esc(v.id)}" data-user="${esc(v.user_id)}" data-url="${esc(url)}"><div class="video-media">${media}</div><div class="shade"></div><div class="video-copy"><button class="creator-link" data-action="profile">@${esc(p.username||"usuario")}</button><p>${esc(v.title||"Nueva publicación")}</p><small>${esc((v.client_origin||v.platform||"LS8").toUpperCase())}</small></div><aside class="video-actions"><button data-action="profile" aria-label="Perfil"><span class="action-avatar">${p.avatar_url?`<img src="${esc(p.avatar_url)}" alt="">`:esc(p.avatar_emoji||"○")}</span></button><button data-action="like" class="${likes.has(v.id)?"selected":""}" aria-label="Me gusta"><i>♥</i><span>${likes.has(v.id)?"Te gusta":"Like"}</span></button><button data-action="comments" aria-label="Comentarios"><i>●</i><span>Comentar</span></button><button data-action="share" aria-label="Compartir"><i>↗</i><span>Compartir</span></button><button data-action="save" class="${isSaved?"selected":""}" aria-label="Guardar"><i>▣</i><span>${isSaved?"Guardado":"Guardar"}</span></button></aside></article>`}

async function loadFeed(reset=true){if(feedBusy)return;feedBusy=true;const feed=$("#videoFeed");if(reset){feedOffset=0;feedDone=false;videos=[];paginationObserver?.disconnect();feed.innerHTML='<div class="state">Buscando señales…</div>'}if(feedDone){feedBusy=false;return}let q=sb.from("videos").select("id,user_id,title,video_url,thumbnail_url,platform,client_origin,created_at,profiles!videos_user_id_fkey(username,avatar_url,avatar_emoji)").order("created_at",{ascending:false}).range(feedOffset,feedOffset+FEED_PAGE-1);if(activeFeed==="siguiendo"){const f=await sb.from("follows").select("followed_id").eq("follower_id",currentUser.id),ids=(f.data||[]).map(x=>x.followed_id);if(!ids.length){feed.innerHTML='<div class="state">Todavía no seguís a ningún creador.</div>';feedBusy=false;return}q=q.in("user_id",ids)}const r=await q;if(r.error){feed.innerHTML='<button class="state error" id="retryFeed">No pudimos cargar el feed. Tocá para reintentar.</button>';$("#retryFeed").onclick=()=>loadFeed(true);feedBusy=false;return}const page=r.data||[];let likes=new Set();if(page.length){const l=await sb.from("video_likes").select("video_id").eq("user_id",currentUser.id).in("video_id",page.map(v=>v.id));likes=new Set((l.data||[]).map(x=>x.video_id))}if(reset)feed.innerHTML="";const start=videos.length;videos.push(...page);feed.insertAdjacentHTML("beforeend",page.map((v,i)=>card(v,start+i,likes)).join(""));feedOffset+=page.length;feedDone=page.length<FEED_PAGE;$("#feedMore")?.remove();if(!feedDone)feed.insertAdjacentHTML("beforeend",'<button class="load-more" id="feedMore" type="button">CARGANDO MÁS SEÑALES <b>↓</b></button>');else if(videos.length)feed.insertAdjacentHTML("beforeend",'<div class="feed-complete">Llegaste al comienzo de LiveScroll.</div>');if(!videos.length)feed.innerHTML='<div class="state">Todavía no hay videos.</div>';bindCards();observe();const more=$("#feedMore");if(more){more.onclick=()=>loadFeed(false);paginationObserver=new IntersectionObserver(entries=>{if(entries[0]?.isIntersecting)loadFeed(false)},{root:feed,rootMargin:"500px"});paginationObserver.observe(more)}feedBusy=false}
function pauseOtherVideos(except=null){$$('.video-card video').forEach(video=>{if(video===except)return;video.dataset.userSound="0";video.muted=true;video.pause()})}
function bindCards(){$$(".video-card").forEach(c=>c.onclick=e=>{const b=e.target.closest("[data-action]");if(b){e.stopPropagation();action(b.dataset.action,c,b);return}const v=c.querySelector("video");if(v){pauseOtherVideos(v);if(v.paused||v.muted){v.dataset.userSound="1";v.muted=false;v.play().catch(()=>{});toast("Sonido activado")}else{v.dataset.userSound="0";v.muted=true;v.pause()}return}if(c.dataset.url)window.open(c.dataset.url,"_blank","noopener")})}
async function action(a,c,b){const id=c.dataset.id;if(a==="profile"){switchView("perfil");loadProfile(c.dataset.user);return}if(a==="comments")return openComments(id);if(a==="like"){if(b.classList.contains("selected"))return;loading(b,true,"···");const r=await sb.rpc("give_like",{p_video_id:id,p_user_id:currentUser.id});loading(b,false);if(r.error||!r.data?.ok)return toast(r.data?.error==="no_self_like"?"No podés dar like a tu video.":"No pudimos registrar el like.","error");b.classList.add("selected");b.querySelector("span").textContent="Te gusta";return toast(`Like registrado${r.data.points?` · +${r.data.points} pt`:""}`)}if(a==="save"){const ids=saved();ids.has(id)?ids.delete(id):ids.add(id);localStorage.setItem(savedKey,JSON.stringify([...ids]));b.classList.toggle("selected",ids.has(id));b.querySelector("span").textContent=ids.has(id)?"Guardado":"Guardar";return toast(ids.has(id)?"Publicación guardada":"Quitada de guardados")}if(a==="share"){const url=`${location.origin}${location.pathname}?video=${encodeURIComponent(id)}`;try{navigator.share?await navigator.share({title:"LiveScroll 8",url}):(await navigator.clipboard.writeText(url),toast("Enlace copiado"))}catch(e){if(e.name!=="AbortError")toast("No pudimos compartir.","error")}}}
function observe(){
  observer?.disconnect();
  const cards=$$(".video-card");
  cards.forEach(card=>{const frame=card.querySelector("iframe");if(frame&&!frame.dataset.src)frame.dataset.src=frame.src;const video=card.querySelector("video");if(!video)return;if(video.dataset.userSound!=="1")video.muted=true;const initialSrc=video.getAttribute("src")||video.currentSrc;if(!video.dataset.src&&initialSrc){video.dataset.src=initialSrc;video.removeAttribute("src");video.load()}if(!video.dataset.stabilityReady){video.dataset.stabilityReady="1";video.addEventListener("error",()=>{card.classList.add("media-error");if(!card.querySelector(".video-retry"))card.querySelector(".video-media")?.insertAdjacentHTML("beforeend",'<div class="video-placeholder video-retry"><b>↻</b><span>Tocá para reintentar</span></div>')});video.addEventListener("playing",()=>card.classList.remove("media-error"))}});
  observer=new IntersectionObserver(entries=>entries.forEach(entry=>{const frame=entry.target.querySelector("iframe"),video=entry.target.querySelector("video"),settings=getLS8Settings(),mayPreload=settings.preload&&!settings.dataSaver;if(frame){if(entry.intersectionRatio>.68&&frame.src==="about:blank"&&frame.dataset.src)frame.src=frame.dataset.src;else if(entry.intersectionRatio<.2&&frame.src!=="about:blank")frame.src="about:blank"}if(!video)return;const shouldLoad=entry.intersectionRatio>0||(entry.isIntersecting&&mayPreload);video.dataset.near=String(shouldLoad);if(shouldLoad){if(!video.getAttribute("src")&&video.dataset.src){video.src=video.dataset.src;video.load()}if(entry.intersectionRatio>.68&&!document.hidden&&settings.autoplay){pauseOtherVideos(video);if(video.dataset.userSound!=="1")video.muted=true;video.play().catch(()=>{})}else{video.dataset.userSound="0";video.muted=true;video.pause()}}else{video.dataset.userSound="0";video.muted=true;video.pause();setTimeout(()=>{if(video.dataset.near==="false"&&video.getAttribute("src")){video.removeAttribute("src");video.load()}},12000)}}),{root:$("#videoFeed"),rootMargin:"85% 0px",threshold:[0,.2,.68]});
  cards.forEach(card=>observer.observe(card));
}

async function openComments(id){$("#modalWrap").innerHTML=`<div class="modal-overlay"><section class="comments-sheet"><header><h3>Comentarios</h3><button id="closeModal">×</button></header><div class="comments-list" id="commentsList"><div class="state">Cargando…</div></div><form id="commentForm" class="comment-form"><input id="commentInput" minlength="3" maxlength="500" placeholder="Escribí un comentario…" required><button class="primary">Enviar</button></form></section></div>`;$("#closeModal").onclick=closeModal;$(".modal-overlay").onclick=e=>{if(e.target.classList.contains("modal-overlay"))closeModal()};$("#commentForm").onsubmit=e=>submitComment(e,id);await loadComments(id)}
