const livePlatforms={kick:{label:"KICK",color:"#53fc18",base:"https://kick.com/"},twitch:{label:"TWITCH",color:"#a970ff",base:"https://twitch.tv/"},youtube:{label:"YOUTUBE",color:"#ff3040",base:"https://youtube.com/"},tiktok:{label:"TIKTOK",color:"#25f4ee",base:"https://tiktok.com/"}};
function liveUrl(p,name){const raw=String(p[`social_${name}`]||"").trim();if(!raw)return"";const direct=safeUrl(raw);if(direct)return direct;const handle=raw.replace(/^@/,"").replace(/^\/+|\/+$/g,"");if(!handle)return"";if(name==="tiktok")return`${livePlatforms[name].base}@${handle}`;if(name==="youtube"&&raw.startsWith("@"))return`${livePlatforms[name].base}@${handle}`;return livePlatforms[name].base+handle}
function activePlatforms(p){return Object.keys(livePlatforms).filter(name=>Boolean(p[`${name}_is_live`]||p.live_platform===name))}
function liveCard(p,names){const colors=names.map(name=>livePlatforms[name].color);return `<article class="live-card" style="--live-a:${colors[0]};--live-b:${colors[1]||colors[0]}"><div class="live-card-glow"></div><header><span class="live-avatar">${p.avatar_url?`<img src="${esc(p.avatar_url)}" alt="">`:esc(p.avatar_emoji||"●")}</span><span><small><i></i> TRANSMITIENDO AHORA</small><b>@${esc(p.username||"creador")}</b></span></header><p>${esc(p.bio||"Una señal está ocurriendo en este momento.")}</p><div class="live-platforms">${names.map(name=>`<span style="--platform:${livePlatforms[name].color}">${livePlatforms[name].label}</span>`).join("")}</div><div class="live-actions">${names.map(name=>{const url=liveUrl(p,name);return url?`<a href="${esc(url)}" target="_blank" rel="noopener">VER EN ${livePlatforms[name].label}<b>↗</b></a>`:""}).join("")||'<button type="button" disabled>ENLACE NO DISPONIBLE</button>'}</div></article>`}
async function loadLives(force=false){const token=++viewToken,grid=$("#liveGrid"),summary=$("#liveSummary");if(!grid)return;grid.innerHTML='<div class="state">Localizando directos…</div>';summary.innerHTML='<i></i><span>Sincronizando señales activas…</span>';let r=await sb.from("profiles").select("id,username,avatar_url,avatar_emoji,bio,is_live,live_platform,kick_is_live,twitch_is_live,youtube_is_live,tiktok_is_live,social_kick,social_twitch,social_youtube,social_tiktok").limit(100);if(r.error)r=await sb.from("profiles").select("id,username,avatar_url,avatar_emoji,bio,is_live,live_platform,social_kick,social_twitch,social_youtube,social_tiktok").eq("is_live",true).limit(100);if(token!==viewToken||activeView!=="directos")return;if(r.error){grid.innerHTML='<button class="state error" id="retryLives">No pudimos consultar los directos. Tocá para reintentar.</button>';$("#retryLives").onclick=()=>loadLives(true);summary.innerHTML='<i class="offline"></i><span>Centro en vivo sin conexión</span>';return}const lives=(r.data||[]).map(p=>({p,names:activePlatforms(p)})).filter(x=>x.p.is_live||x.names.length).map(x=>({p:x.p,names:x.names.length?x.names:[x.p.live_platform].filter(Boolean)})).filter(x=>x.names.length);summary.innerHTML=`<i class="${lives.length?"":"offline"}"></i><span>${lives.length?`${lives.length} ${lives.length===1?"creador está":"creadores están"} transmitiendo ahora`:"No hay transmisiones activas en este momento"}</span>`;grid.innerHTML=lives.map(x=>liveCard(x.p,x.names)).join("")||'<div class="live-empty"><b>El pulso está en calma.</b><span>Cuando alguien inicie directo aparecerá acá automáticamente.</span></div>';if(force)toast("Directos actualizados")}
