function youtubeId(url){try{const parsed=new URL(url),host=parsed.hostname.replace(/^www\./,"");if(host==="youtu.be")return parsed.pathname.split("/").filter(Boolean)[0]||"";if(host.endsWith("youtube.com")){if(parsed.searchParams.get("v"))return parsed.searchParams.get("v");const parts=parsed.pathname.split("/").filter(Boolean);if(["shorts","embed","live"].includes(parts[0]))return parts[1]||""}}catch{}return""}
function enhanceMedia(root=document){
  root.querySelectorAll?.(".video-card").forEach(card=>{if(card.dataset.mediaReady)return;card.dataset.mediaReady="1";const id=youtubeId(card.dataset.url),holder=card.querySelector(".video-media");if(id&&holder&&!holder.querySelector(".youtube-preview"))holder.innerHTML=`<button class="youtube-preview" data-youtube-play="${esc(id)}" type="button" aria-label="Reproducir video de YouTube"><img src="https://i.ytimg.com/vi/${encodeURIComponent(id)}/hqdefault.jpg" alt="" loading="eager"><i>▶</i><span>TOCÁ PARA REPRODUCIR</span></button>`});
  root.querySelectorAll?.(".profile-video").forEach(button=>{if(button.dataset.mediaReady||button.querySelector("img"))return;button.dataset.mediaReady="1";const url=safeUrl(button.dataset.url),id=youtubeId(url);if(id){const image=document.createElement("img");image.src=`https://i.ytimg.com/vi/${encodeURIComponent(id)}/hqdefault.jpg`;image.alt="";button.prepend(image);button.classList.add("has-media");return}if(/\.(mp4|webm|mov)(\?|$)/i.test(url)||url.includes("r2.dev")){const video=document.createElement("video");video.src=url;video.muted=true;video.playsInline=true;video.preload="metadata";video.addEventListener("loadedmetadata",()=>{try{video.currentTime=Math.min(.25,Math.max(0,video.duration-.05))}catch{}},{once:true});button.prepend(video);button.classList.add("has-media")}})
}
