  const networks=[["Instagram",p.social_instagram],["Kick",p.social_kick],["Twitch",p.social_twitch],["YouTube",p.social_youtube],["TikTok",p.social_tiktok]].map(([name,url])=>[name,safeUrl(url)]).filter(([,url])=>url),section=document.createElement("section");section.className="profile-showcase";
