async function optimizeProfileImage(file,kind){if(!file?.type.startsWith("image/"))throw new Error("Elegí una imagen válida.");if(file.size>6*1024*1024)throw new Error("La imagen supera los 6 MB.");const image=await createImageBitmap(file),limit=kind==="avatar"?720:kind==="cover"?1800:1600,scale=Math.min(1,limit/Math.max(image.width,image.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext("2d",{alpha:false}).drawImage(image,0,0,canvas.width,canvas.height);image.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,"image/webp",.84));if(!blob)throw new Error("No pudimos procesar la imagen.");return blob}
