async function uploadProfileImage(kind,file,p){const columns={avatar:"avatar_url",cover:"cover_url",background:"profile_side_image_url"},column=columns[kind],status=$("#profileMediaStatus");if(!column)return false;profileMediaFailures.delete(kind);if(status)status.textContent="Optimizando y subiendo…";try{const blob=await optimizeProfileImage(file,kind),path=`${currentUser.id}/ls8-${kind}-${Date.now()}.webp`,uploaded=await sb.storage.from("avatars").upload(path,blob,{cacheControl:"31536000",contentType:"image/webp",upsert:false});if(uploaded.error)throw uploaded.error;const url=sb.storage.from("avatars").getPublicUrl(path).data.publicUrl,updated=await sb.from("profiles").update({[column]:url}).eq("id",currentUser.id).select(column).maybeSingle();if(updated.error)throw updated.error;if(!updated.data?.[column])throw new Error("La imagen subió, pero el perfil no confirmó el cambio.");p[column]=updated.data[column];currentProfile={...currentProfile,[column]:updated.data[column]};if(status)status.textContent="Imagen guardada correctamente.";const preview=$(`[data-profile-preview="${kind}"]`);if(preview){preview.style.backgroundImage=`url('${updated.data[column]}')`;preview.classList.add("has-image");preview.textContent=""}if(kind==="avatar")avatar($("#topAvatar"),currentProfile);return true}catch(error){profileMediaFailures.add(kind);if(status)status.textContent=error.message||"No pudimos subir la imagen.";toast(error.message||"No pudimos subir la imagen.","error");return false}}
function enhanceProfileEditorMedia(p){const form=$("#profileEditor"),header=form?.querySelector("header");if(!form||!header||form.querySelector(".profile-media-editor"))return;const position=Math.max(0,Math.min(100,Number(p.cover_position_y??50)||50)),block=document.createElement("section");block.className="profile-media-editor";block.innerHTML=`<div class="profile-media-title"><span>IMAGEN DEL PERFIL</span><small>Optimización automática · máximo 6 MB</small></div><div class="profile-media-grid"><label><span class="profile-media-preview avatar-preview ${p.avatar_url?"has-image":""}" data-profile-preview="avatar" ${p.avatar_url?`style="background-image:url('${esc(safeUrl(p.avatar_url))}')"`:""}>${p.avatar_url?"":"FOTO"}</span><b>Cambiar foto</b><input type="file" accept="image/*" data-profile-file="avatar"></label><label><span class="profile-media-preview cover-preview ${p.cover_url?"has-image":""}" data-profile-preview="cover" ${p.cover_url?`style="background-image:url('${esc(safeUrl(p.cover_url))}');background-position:center ${position}%"`:""}>${p.cover_url?"":"PORTADA"}</span><b>Cambiar portada</b><input type="file" accept="image/*" data-profile-file="cover"></label><label><span class="profile-media-preview background-preview ${p.profile_side_image_url?"has-image":""}" data-profile-preview="background" ${p.profile_side_image_url?`style="background-image:url('${esc(safeUrl(p.profile_side_image_url))}')"`:""}>${p.profile_side_image_url?"":"FONDO"}</span><b>Cambiar fondo</b><input type="file" accept="image/*" data-profile-file="background"></label></div><label class="cover-position">Posición vertical de portada <output>${position}%</output><input name="cover_position_y" type="range" min="0" max="100" value="${position}"></label><p id="profileMediaStatus" aria-live="polite">Los cambios visuales se aplican sin recargar LS8.</p>`;header.after(block);block.querySelectorAll("[data-profile-file]").forEach(input=>input.onchange=()=>{const file=input.files?.[0];if(file)uploadProfileImage(input.dataset.profileFile,file,p)});const range=form.cover_position_y,output=block.querySelector("output"),preview=block.querySelector('[data-profile-preview="cover"]');range.oninput=()=>{output.value=`${range.value}%`;if(preview)preview.style.backgroundPosition=`center ${range.value}%`}}
