async function loadUsersDirectory(){const target=$("#usersGrid"),term=$("#usersSearch")?.value.trim()||"",clean=term.replace(/[%_]/g,"");if(!target)return;target.innerHTML='<div class="state">Buscando comunidad…</div>';let query=sb.from("profiles").select("id,username,avatar_url,avatar_emoji,bio,is_creator,is_creator_verified").order("username").limit(120);if(directoryMode==="creators")query=query.eq("is_creator",true);if(clean.length>=2)query=query.ilike("username",`%${clean}%`);let r=await query;if(r.error){console.warn("LS8 directorio avanzado no disponible",r.error);let fallback=sb.from("profiles").select("id,username,avatar_url,avatar_emoji,is_creator").order("username").limit(80);if(directoryMode==="creators")fallback=fallback.eq("is_creator",true);if(clean.length>=2)fallback=fallback.ilike("username",`%${clean}%`);r=await fallback}if(r.error){console.error("LS8 directorio compatible falló",r.error);target.innerHTML='<button class="state error" id="retryUsers">No pudimos cargar los usuarios. Tocá para reintentar.</button>';$("#retryUsers").onclick=loadUsersDirectory;return}target.innerHTML=(r.data||[]).map(userDirectoryCard).join("")||'<div class="empty-card"><b>No encontramos perfiles.</b><span>Probá con otro nombre.</span></div>';$$('[data-directory-profile]').forEach(button=>button.onclick=async()=>{await switchView("perfil");await loadProfile(button.dataset.directoryProfile)})}
async function loadAdmin(){const target=$("#adminView");if(!target)return;if(!currentProfile.is_admin){target.innerHTML='<div class="empty-card admin-denied"><b>Acceso reservado.</b><span>Este centro solamente está disponible para administradores.</span></div>';return}target.innerHTML='<div class="state">Cargando centro de control…</div>';let r=await sb.rpc("admin_get_users_v2",{p_query:null}),users=[];if(!r.error&&r.data?.ok)users=r.data.users||[];else{console.warn("LS8 Admin v2 no disponible",r.error||r.data);r=await sb.rpc("admin_list_all_users");if(!r.error)users=Array.isArray(r.data)?r.data:(r.data?.users||[])}if(r.error){console.error("LS8 Admin compatible falló",r.error);target.innerHTML='<button class="state error" id="retryAdmin">No pudimos abrir Admin. Tocá para reintentar.</button>';$("#retryAdmin").onclick=loadAdmin;return}const creators=users.filter(u=>u.is_creator),verified=creators.filter(u=>u.is_creator_verified);target.innerHTML=`<div class="admin-summary"><div><b>${users.length}</b><span>Usuarios</span></div><div><b>${creators.length}</b><span>Creadores</span></div><div><b>${verified.length}</b><span>Verificados</span></div></div><input class="search" id="adminSearch" type="search" placeholder="Buscar usuario o correo"><div class="admin-users" id="adminUsers">${users.map(adminUserCard).join("")}</div>`;$("#adminSearch").oninput=e=>{clearTimeout(usersTimer);usersTimer=setTimeout(()=>searchAdminUsers(e.target.value),260)};bindAdminActions()}
function adminUserCard(u){return `<article class="admin-user-card" data-admin-user="${esc(u.id)}"><div><small>${u.ban_reason?"BANEADO":u.is_blocked?"BLOQUEADO":u.is_creator?"CREADOR":"USUARIO"}</small><b>@${esc(u.username||"usuario")}</b><em>${esc(u.email||"Sin correo visible")} · ${Number(u.points_balance||0)} pts · ${esc(u.plan_id||"standard")}</em></div><div class="admin-user-actions"><button data-admin-profile="${esc(u.id)}">Ver perfil</button><button data-admin-creator="${esc(u.id)}" data-enabled="${u.is_creator?"1":"0"}">${u.is_creator?"Quitar creador":"Dar creador"}</button>${u.is_creator?`<button data-admin-verify="${esc(u.id)}" data-enabled="${u.is_creator_verified?"1":"0"}">${u.is_creator_verified?"Quitar verificado":"Verificar"}</button>`:""}<button data-admin-plan="${esc(u.id)}">Cambiar plan</button>${u.ban_reason||u.is_blocked?`<button class="safe" data-admin-unblock="${esc(u.id)}">Desbloquear</button>`:`<button class="danger" data-admin-ban="${esc(u.id)}" data-name="${esc(u.username||"usuario")}">Bloquear</button>`}</div></article>`}
