async function buyStoreProduct(button){const type=button.dataset.buyType,id=button.dataset.buyId,price=Number(button.dataset.price||0);if(price>Number(currentProfile.points_balance||0))return toast("No tenés puntos suficientes.","error");loading(button,true,"OBTENIENDO…");const calls={badge:["buy_store_badge",{p_badge_id:id}],emoji:["buy_emoji",{p_user_id:currentUser.id,p_emoji_id:id}],item:["buy_store_item",{p_item_id:id}]},[rpc,args]=calls[type],r=await sb.rpc(rpc,args);loading(button,false);if(r.error||!r.data?.ok){const code=r.data?.error;return toast(/ya_/.test(code||"")?"Ya está en tu colección.":/agotad/.test(code||"")?"Esta edición se agotó.":"No pudimos completar la compra.","error")}currentProfile.points_balance=Number(r.data.new_balance??Math.max(0,Number(currentProfile.points_balance||0)-price));toast(price?"Compra completada sin recargar":"Recompensa agregada");loadStore()}

let selectedCollectionBadges=[];
async function loadCollection(){const target=$("#collectionView");target.innerHTML='<div class="state">Abriendo colección…</div>';const [owned,equipped,emojis,items]=await Promise.all([sb.from("user_badges").select("badge_name,badge_icon,earned_at").eq("user_id",currentUser.id),sb.rpc("get_equipped_profile_badges",{p_user_id:currentUser.id}),sb.from("user_unlocked_emojis").select("emoji").eq("user_id",currentUser.id),sb.from("user_unlocked_items").select("item_id").eq("user_id",currentUser.id)]);selectedCollectionBadges=(equipped.data||[]).sort((a,b)=>Number(a.slot_number)-Number(b.slot_number)).map(x=>x.badge_name).slice(0,3);target.innerHTML=`<section class="collection-equipped"><header><span>IDENTIDAD PÚBLICA</span><b><em id="collectionCount">${selectedCollectionBadges.length}</em>/3 equipadas</b></header><div id="equippedPreview"></div><button class="primary" id="saveCollection" type="button">GUARDAR IDENTIDAD</button></section><section class="collection-section"><h3>Medallas</h3><p>Elegí hasta tres. La primera será tu favorita.</p><div class="collection-grid">${(owned.data||[]).map(b=>`<button class="collection-item ${selectedCollectionBadges.includes(b.badge_name)?"selected":""}" data-collection-badge="${esc(b.badge_name)}"><i>${esc(b.badge_icon||"🏅")}</i><span><b>${esc(b.badge_name)}</b><small>${b.earned_at?new Date(b.earned_at).toLocaleDateString("es-AR"):"Colección LS"}</small></span></button>`).join("")||'<div class="empty-card"><b>Todavía no tenés medallas.</b><span>Conseguí la primera desde la Tienda.</span></div>'}</div></section><div class="collection-summary"><div><b>${(owned.data||[]).length}</b><span>Medallas</span></div><div><b>${(emojis.data||[]).length}</b><span>Emojis</span></div><div><b>${(items.data||[]).length}</b><span>Extras</span></div></div>`;renderEquippedPreview();$$('[data-collection-badge]').forEach(button=>button.onclick=()=>toggleCollectionBadge(button));$("#saveCollection").onclick=saveCollection}
function renderEquippedPreview(){const preview=$("#equippedPreview");if(!preview)return;preview.innerHTML=[0,1,2].map(i=>selectedCollectionBadges[i]?`<span><i>${i===0?"★":"◆"}</i><b>${esc(selectedCollectionBadges[i])}</b></span>`:'<span class="empty"><i>＋</i><b>Espacio libre</b></span>').join("");$("#collectionCount").textContent=selectedCollectionBadges.length}
function toggleCollectionBadge(button){const name=button.dataset.collectionBadge,index=selectedCollectionBadges.indexOf(name);if(index>=0){selectedCollectionBadges.splice(index,1);button.classList.remove("selected")}else{if(selectedCollectionBadges.length>=3)return toast("Podés equipar hasta 3 medallas.","error");selectedCollectionBadges.push(name);button.classList.add("selected")}renderEquippedPreview()}
async function saveCollection(){const button=$("#saveCollection");loading(button,true,"GUARDANDO…");const r=await sb.rpc("set_equipped_profile_badges",{p_badge_names:selectedCollectionBadges.slice(0,3)});loading(button,false);if(r.error||!r.data?.ok)return toast("No pudimos guardar las medallas.","error");toast("Identidad actualizada sin recargar")}

async function loadMissions(){const target=$("#missionsView");target.innerHTML='<div class="state">Preparando retos…</div>';const r=await sb.rpc("get_daily_challenges");if(r.error||!r.data?.ok){target.innerHTML='<button class="state error" id="retryMissions">No pudimos cargar las misiones. Tocá para reintentar.</button>';$("#retryMissions").onclick=loadMissions;return}const challenges=r.data.challenges||[],done=challenges.filter(x=>Number(x.progress)>=Number(x.target)).length;target.innerHTML=`<section class="mission-summary"><small>REINICIO AUTOMÁTICO · ARGENTINA</small><b>${done}/${challenges.length} completadas</b><span>${done===challenges.length?"¡Completaste todos los retos de hoy!":"Tu progreso se registra mientras usás LiveScroll."}</span></section><div class="mission-list">${challenges.map(item=>{const progress=Math.min(Number(item.progress||0),Number(item.target||1)),percent=Math.round(progress/Number(item.target||1)*100);return `<article class="mission-card ${percent>=100?"done":""}"><i>${esc(item.emoji||"◉")}</i><span><b>${esc(item.title||"Misión")}</b><small>${progress}/${item.target}</small><em><u style="width:${percent}%"></u></em></span><strong>${percent>=100?"LISTO":`${percent}%`}</strong></article>`}).join("")}</div>`}

async function loadPlansView(){const target=$("#plansView");target.innerHTML='<div class="state">Cargando planes…</div>';const r=await sb.from("plans").select("*").order("price_ars",{ascending:true});if(r.error){target.innerHTML='<div class="state error">No pudimos cargar los planes.</div>';return}target.innerHTML=`<div class="plans-grid">${(r.data||[]).map(p=>`<article class="plan-card ${p.id===currentProfile.plan_id?"current":""}"><small>${p.id===currentProfile.plan_id?"TU PLAN":"PLAN LIVESCROLL"}</small><h3>${esc(p.name||p.id)}</h3><b>${Number(p.price_ars||0)?`$${Number(p.price_ars).toLocaleString("es-AR")}/mes`:"GRATIS"}</b><ul><li>Boost x${Number(p.boost_multiplier||1)}</li><li>Tope diario: ${Number(p.daily_cap_normal||0).toLocaleString("es-AR")} pts</li><li>${Number(p.max_pinned_videos||0)} videos anclados</li><li>Comisión: ${Math.round(Number(p.commission_pct||0)*100)}%</li></ul>${p.id===currentProfile.plan_id?'<button disabled>PLAN ACTUAL</button>':`<button data-buy-plan="${esc(p.id)}">MEJORAR CON PUNTOS</button>`}</article>`).join("")}</div>`;$$('[data-buy-plan]').forEach(button=>button.onclick=()=>buyPlan(button))}
async function buyPlan(button){loading(button,true,"ACTIVANDO…");const r=await sb.rpc("buy_plan_with_points",{p_user_id:currentUser.id,p_plan_id:button.dataset.buyPlan});loading(button,false);if(r.error||!r.data?.ok)return toast(r.data?.error==="saldo_insuficiente"?"No tenés puntos suficientes.":"No pudimos cambiar el plan.","error");currentProfile.plan_id=button.dataset.buyPlan;if(r.data.new_balance!=null)currentProfile.points_balance=Number(r.data.new_balance);toast("Plan actualizado sin recargar");loadPlansView()}

async function loadCreatorAccess(){const target=$("#creatorAccessView"),[count,status]=await Promise.all([sb.from("videos").select("id",{count:"exact",head:true}).eq("user_id",currentUser.id),sb.rpc("get_my_creator_program_status")]),videos=count.count||0,creator=currentProfile.is_creator===true,verified=currentProfile.is_creator_verified===true||status.data?.is_creator_verified===true;target.innerHTML=`<section class="creator-program-hero"><small>PROGRAMA DE CREADORES</small><h3>${verified?"Creador verificado":creator?"Ya sos Creador":"Convertí tu perfil en Creador"}</h3><p>Accedé a redes profesionales, Directos y herramientas especiales de identidad.</p></section><div class="creator-requirements"><article class="${videos>=5?"done":""}"><i>${videos>=5?"✓":"1"}</i><span><b>5 videos publicados</b><small>${videos}/5 completados</small></span></article><article class="done"><i>✓</i><span><b>Cuenta activa</b><small>Sesión e identidad verificadas</small></span></article><article class="${status.data?.terms_version?"done":""}"><i>${status.data?.terms_version?"✓":"3"}</i><span><b>Términos del programa</b><small>${status.data?.terms_version?"Aceptados":"Se aceptan al enviar"}</small></span></article></div>${verified?'<div class="creator-status verified">◆ VERIFICADO OFICIALMENTE</div>':creator?'<div class="creator-status">Tu acceso Creador está activo. La verificación final depende del Admin.</div>':`<label class="creator-terms"><input id="creatorTerms" type="checkbox"> <span>Acepto los términos del Programa de Creadores 1.0.</span></label><button class="primary" id="requestCreator" ${videos<5?"disabled":""}>ENVIAR SOLICITUD</button>`}`;if($("#requestCreator"))$("#requestCreator").onclick=requestCreatorLS8}
async function requestCreatorLS8(){if(!$("#creatorTerms").checked)return toast("Tenés que aceptar los términos.","error");const button=$("#requestCreator");loading(button,true,"ENVIANDO…");let accepted=await sb.rpc("accept_creator_program_terms",{p_version:"1.0"});if(accepted.error||!accepted.data?.ok){loading(button,false);return toast("No pudimos registrar los términos.","error")}const r=await sb.rpc("request_creator_access");loading(button,false);if(r.error||!r.data?.ok){const messages={videos_insuficientes:"Necesitás al menos 5 videos.",cuenta_muy_nueva:"La cuenta debe tener 7 días.",cuenta_sancionada:"Tu cuenta tiene una sanción.",solicitud_pendiente:"Tu solicitud ya está en revisión."};return toast(messages[r.data?.error]||"No pudimos enviar la solicitud.","error")}toast("Solicitud enviada al Admin");loadCreatorAccess()}

async function loadNews(){const target=$("#newsView");target.innerHTML='<div class="state">Cargando historial…</div>';let r=await sb.from("changelog_entries").select("version,display_version,category,content,created_at").order("version",{ascending:false}).limit(80);if(r.error)r=await sb.from("changelog_entries").select("version,display_version,category,content").order("version",{ascending:false}).limit(80);if(r.error){target.innerHTML='<div class="state error">No pudimos cargar las novedades.</div>';return}const entries=(r.data||[]).filter(x=>/^8(?:\.|$)/.test(String(x.display_version||""))||!String(x.display_version||"").startsWith("7"));target.innerHTML=`<div class="news-timeline">${entries.map(x=>`<article><i></i><span><small>${esc(String(x.category||"mejora").toUpperCase())}</small><b>${esc(x.display_version||`Revisión ${x.version}`)}</b><p>${esc(x.content||"")}</p></span></article>`).join("")||'<div class="empty-card"><b>LS8 recién comienza.</b><span>Las próximas evoluciones aparecerán acá.</span></div>'}</div>`}
