const loadAdminUsersBase=loadAdmin;loadAdmin=async function(){await loadAdminUsersBase();const target=$("#adminView");if(!target||!currentProfile.is_admin||target.querySelector(".admin-global-control"))return;const [visibility,stats,applications,redemptions]=await Promise.all([sb.rpc("get_app_visibility"),sb.rpc("admin_get_stats"),sb.rpc("admin_get_creator_applications"),sb.from("redemptions").select("id,user_id,points,amount_ars,status,created_at,profiles!redemptions_user_id_fkey(username)").eq("status","pending").order("created_at")]);const state=visibility.data||{},summary=stats.data||{},pendingApps=(applications.data||[]).filter(x=>x.status==="pending"),pendingRedeems=redemptions.data||[],control=document.createElement("section");control.className="admin-global-control";control.innerHTML=`<div class="admin-control-title"><span><small>CONTROL GLOBAL LS8</small><b>Disponibilidad de servicios</b></span><em>Los administradores conservan el acceso.</em></div><div class="admin-switches"><button data-global-service="plans" data-status="${esc(state.plans_visibility||"open")}"><i></i><span><b>Planes</b><small>${state.plans_visibility==="closed"?"Cerrados para usuarios":"Abiertos para todos"}</small></span><strong>${state.plans_visibility==="closed"?"ABRIR":"CERRAR"}</strong></button><button data-global-service="wallet" data-status="${esc(state.wallet_visibility||"open")}"><i></i><span><b>Billetera</b><small>${state.wallet_visibility==="closed"?"Cerrada para usuarios":"Abierta para todos"}</small></span><strong>${state.wallet_visibility==="closed"?"ABRIR":"CERRAR"}</strong></button></div><div class="admin-platform-stats"><div><b>${Number(summary.total_users||0)}</b><span>Usuarios totales</span></div><div><b>${Number(summary.total_videos||0)}</b><span>Videos</span></div><div><b>${pendingApps.length}</b><span>Solicitudes Creador</span></div><div><b>${pendingRedeems.length}</b><span>Canjes pendientes</span></div></div>${pendingApps.length?`<div class="admin-pending"><h3>Solicitudes de Creador</h3>${pendingApps.map(x=>`<article><span><b>@${esc(x.username||"usuario")}</b><small>${Number(x.video_count||0)} videos · ${Number(x.account_days||0)} días</small></span><div><button data-app-decision="approved" data-app-id="${esc(x.application_id||x.id)}">Aprobar</button><button class="danger" data-app-decision="rejected" data-app-id="${esc(x.application_id||x.id)}">Rechazar</button></div></article>`).join("")}</div>`:""}${pendingRedeems.length?`<div class="admin-pending"><h3>Canjes pendientes</h3>${pendingRedeems.map(x=>`<article><span><b>@${esc(x.profiles?.username||"usuario")}</b><small>${Number(x.points||0).toLocaleString("es-AR")} pts · $${Number(x.amount_ars||0).toLocaleString("es-AR")}</small></span><div><button data-redeem-decision="approve" data-redeem-id="${esc(x.id)}">Pagado</button><button class="danger" data-redeem-decision="reject" data-redeem-id="${esc(x.id)}">Rechazar</button></div></article>`).join("")}</div>`:""}`;target.prepend(control);$$('[data-global-service]').forEach(button=>button.onclick=()=>toggleGlobalService(button));$$('[data-app-decision]').forEach(button=>button.onclick=()=>decideCreatorApplication(button));$$('[data-redeem-decision]').forEach(button=>button.onclick=()=>decideRedemption(button))};
async function toggleGlobalService(button){const service=button.dataset.globalService,next=button.dataset.status==="closed"?"open":"closed",rpc=service==="plans"?"admin_set_plans_visibility":"admin_set_wallet_visibility";loading(button,true,next==="open"?"ABRIENDO…":"CERRANDO…");const changed=await sb.rpc(rpc,{p_status:next});if(changed.error||!changed.data?.ok){loading(button,false);return toast(`No pudimos cambiar ${service==="plans"?"Planes":"Billetera"}.`,"error")}const verified=await sb.rpc("get_app_visibility"),saved=String(verified.data?.[`${service}_visibility`]||"");if(verified.error||saved!==next){loading(button,false);return toast("Supabase no confirmó el cambio.","error")}toast(next==="closed"?`${service==="plans"?"Planes":"Billetera"} cerrado para usuarios`:`${service==="plans"?"Planes":"Billetera"} abierto nuevamente`);loadAdmin()}
