const LS8_SETTINGS_KEY="livescroll8_settings";
function getLS8Settings(){try{return{autoplay:true,dataSaver:false,reducedMotion:matchMedia("(prefers-reduced-motion: reduce)").matches,season:"auto",...JSON.parse(localStorage.getItem(LS8_SETTINGS_KEY)||"{}")}}catch{return{autoplay:true,dataSaver:false,reducedMotion:false,season:"auto"}}}
function automaticLS8Season(){const d=new Date(),m=d.getMonth()+1,day=d.getDate();if(m===10&&day>=25)return"halloween";if(m===12&&day>=8&&day<=26)return"christmas";if(m===9&&day>=21)return"spring";return"normal"}
function applyLS8Settings(){const settings=getLS8Settings(),season=settings.season==="off"?"normal":settings.season==="auto"?automaticLS8Season():settings.season;document.documentElement.dataset.reducedMotion=settings.reducedMotion?"1":"0";document.documentElement.dataset.dataSaver=settings.dataSaver?"1":"0";document.body.dataset.ls8Season=season;$$('.video-card video').forEach(video=>video.preload=settings.dataSaver?"none":"metadata")}
function loadSettings(){const target=$("#settingsView"),s=getLS8Settings();target.innerHTML=`<div class="settings-list"><label><span><b>Reproducción automática</b><small>Los videos visibles comienzan silenciados.</small></span><input type="checkbox" data-setting="autoplay" ${s.autoplay?"checked":""}></label><label><span><b>Ahorro de datos</b><small>Carga menos contenido anticipadamente.</small></span><input type="checkbox" data-setting="dataSaver" ${s.dataSaver?"checked":""}></label><label><span><b>Reducir movimiento</b><small>Desactiva partículas y animaciones decorativas.</small></span><input type="checkbox" data-setting="reducedMotion" ${s.reducedMotion?"checked":""}></label><div class="season-setting"><span><b>Ambiente de temporada</b><small>Solo cambia la apariencia de este dispositivo.</small></span><select data-setting="season"><option value="auto">Automático</option><option value="spring">Primavera</option><option value="halloween">Halloween</option><option value="christmas">Navidad</option><option value="off">Desactivado</option></select></div></div><div class="settings-device"><small>CONFIGURACIÓN LOCAL LS8</small><b>Los cambios se aplican al instante</b><span>No modifican LS6 ni LS7.</span></div>`;target.querySelector('[data-setting="season"]').value=s.season;target.querySelectorAll('[data-setting]').forEach(input=>input.onchange=()=>saveLS8Setting(input))}
function saveLS8Setting(input){const settings=getLS8Settings(),key=input.dataset.setting;settings[key]=input.type==="checkbox"?input.checked:input.value;localStorage.setItem(LS8_SETTINGS_KEY,JSON.stringify(settings));applyLS8Settings();if(key==="autoplay"&&!settings.autoplay)pauseOtherVideos();toast("Configuración aplicada")}
document.addEventListener("play",event=>{const video=event.target;if(!(video instanceof HTMLVideoElement))return;const settings=getLS8Settings();if(!settings.autoplay&&video.dataset.userSound!=="1")video.pause()},{capture:true});
const preferenceObserver=new MutationObserver(()=>applyLS8Settings());preferenceObserver.observe($("#videoFeed"),{childList:true});applyLS8Settings();
const switchViewControlBase=switchView;switchView=async function(view){await switchViewControlBase(view);if(view==="configuracion")loadSettings()};

const getLS8SettingsBase=getLS8Settings;getLS8Settings=function(){return{preload:true,effects:true,glass:true,shadows:true,performanceMode:false,...getLS8SettingsBase()}};
const applyLS8SettingsBase=applyLS8Settings;applyLS8Settings=function(){applyLS8SettingsBase();const s=getLS8Settings(),root=document.documentElement;root.dataset.effects=s.effects?"1":"0";root.dataset.glass=s.glass?"1":"0";root.dataset.shadows=s.shadows?"1":"0";root.dataset.performance=s.performanceMode?"1":"0";$$('.video-card video').forEach(video=>video.preload=s.dataSaver||!s.preload?"none":"metadata")};
loadSettings=function(){const target=$("#settingsView"),s=getLS8Settings();target.innerHTML=`<div class="settings-hub"><button id="openGraphics"><i>◫</i><span><small>AJUSTE AVANZADO</small><b>Gráficos y Rendimiento</b><em>Video, efectos y consumo del dispositivo</em></span><strong>›</strong></button></div><div class="settings-list"><div class="season-setting"><span><b>Ambiente de temporada</b><small>Solo cambia la apariencia de este dispositivo.</small></span><select data-setting="season"><option value="auto">Automático</option><option value="spring">Primavera</option><option value="halloween">Halloween</option><option value="christmas">Navidad</option><option value="off">Desactivado</option></select></div></div><div class="settings-device"><small>CONFIGURACIÓN LOCAL LS8</small><b>El mismo diseño, adaptado a tu dispositivo</b><span>No modifica LS6, LS7 ni la experiencia de otros usuarios.</span></div>`;target.querySelector('[data-setting="season"]').value=s.season;target.querySelector('[data-setting="season"]').onchange=e=>saveLS8Setting(e.currentTarget);$("#openGraphics").onclick=()=>switchView("graficos")};
const graphicsOptions=[
  {key:"autoplay",title:"Reproducción automática",description:"Inicia el video visible, siempre silenciado."},
  {key:"preload",title:"Precargar próximo video",description:"Reduce la espera al deslizar, usando un poco más de datos."},
  {key:"dataSaver",title:"Ahorro de datos",description:"Evita cargas anticipadas y fondos multimedia pesados."},
  {key:"reducedMotion",title:"Reducir movimiento",description:"Desactiva animaciones y transiciones decorativas."},
  {key:"effects",title:"Fondos y efectos ambientales",description:"Muestra atmósferas, temporadas y fondos de creador."},
  {key:"glass",title:"Desenfoque tipo vidrio",description:"Activa el efecto translúcido de barras y paneles."},
  {key:"shadows",title:"Sombras profundas",description:"Añade volumen visual a tarjetas y ventanas."}
];
function loadGraphicsSettings(){const target=$("#graphicsView"),s=getLS8Settings();target.innerHTML=`<section class="performance-preset ${s.performanceMode?"active":""}"><div><small>AJUSTE RECOMENDADO</small><b>Modo rendimiento</b><span>Ideal para celulares antiguos o cuando querés ahorrar batería.</span></div><button id="performancePreset">${s.performanceMode?"DESACTIVAR":"ACTIVAR"}</button></section><div class="graphics-score"><span><small>PERFIL ACTUAL</small><b>${s.performanceMode?"Rendimiento":"Personalizado"}</b></span><i>${s.performanceMode?"LIGERO":"LS8 COMPLETO"}</i></div><div class="graphics-list">${graphicsOptions.map(option=>`<label><span><b>${option.title}</b><small>${option.description}</small></span><input type="checkbox" data-graphics="${option.key}" ${s[option.key]?"checked":""}></label>`).join("")}</div><button class="restore-graphics" id="restoreGraphics">RESTAURAR VALORES RECOMENDADOS</button>`;$("#performancePreset").onclick=togglePerformancePreset;$("#restoreGraphics").onclick=restoreGraphicsSettings;$$('[data-graphics]').forEach(input=>input.onchange=()=>saveGraphicsSetting(input))}
function saveGraphicsSetting(input){const s=getLS8Settings();s[input.dataset.graphics]=input.checked;s.performanceMode=false;localStorage.setItem(LS8_SETTINGS_KEY,JSON.stringify(s));applyLS8Settings();if(input.dataset.graphics==="autoplay"&&!input.checked)pauseOtherVideos();loadGraphicsSettings();toast("Rendimiento actualizado")}
function togglePerformancePreset(){const s=getLS8Settings(),enable=!s.performanceMode;Object.assign(s,enable?{performanceMode:true,autoplay:false,preload:false,dataSaver:true,reducedMotion:true,effects:false,glass:false,shadows:false}:{performanceMode:false,autoplay:true,preload:true,dataSaver:false,reducedMotion:false,effects:true,glass:true,shadows:true});localStorage.setItem(LS8_SETTINGS_KEY,JSON.stringify(s));applyLS8Settings();if(enable)pauseOtherVideos();loadGraphicsSettings();toast(enable?"Modo rendimiento activado":"Experiencia completa restaurada")}
function restoreGraphicsSettings(){const s=getLS8Settings();Object.assign(s,{performanceMode:false,autoplay:true,preload:true,dataSaver:false,reducedMotion:false,effects:true,glass:true,shadows:true});localStorage.setItem(LS8_SETTINGS_KEY,JSON.stringify(s));applyLS8Settings();loadGraphicsSettings();toast("Valores recomendados restaurados")}
const switchViewGraphicsBase=switchView;switchView=async function(view){await switchViewGraphicsBase(view);if(view==="graficos")loadGraphicsSettings()};$("#backSettings").onclick=()=>switchView("configuracion");applyLS8Settings();

function feedMediaOverlay(card,state="loading"){
  const holder=card?.querySelector(".video-media");if(!holder)return null;let overlay=holder.querySelector(".feed-media-state");
  if(!overlay){overlay=document.createElement("div");overlay.className="feed-media-state";holder.appendChild(overlay)}
  overlay.dataset.state=state;
  if(state==="loading")overlay.innerHTML='<i></i><b>Preparando video…</b><span>LS8 está cargando la señal</span>';
  else overlay.innerHTML=`<i>↻</i><b>No pudimos reproducirlo</b><span>${esc(card.dataset.mediaReason||"Puede ser un formato no compatible o una conexión lenta.")}</span><div><button data-feed-media-retry type="button">REINTENTAR</button>${card.dataset.url?'<button data-feed-media-open type="button">ABRIR ORIGINAL</button>':""}</div>`;
  return overlay;
}
function guardFeedVideo(card,video){if(video.dataset.feedGuard)return;video.dataset.feedGuard="1";let timer=0;const clear=()=>{clearTimeout(timer);delete card.dataset.mediaReason;card.classList.remove("feed-media-failed");card.querySelector(".feed-media-state")?.remove();card.querySelector(".video-retry")?.remove()},fail=()=>{clearTimeout(timer);card.querySelector(".video-retry")?.remove();card.dataset.mediaReason=video.error?.code===4?"Este video usa un formato que tu dispositivo no puede reproducir.":"La conexión está lenta o el archivo no respondió.";card.classList.add("feed-media-failed");feedMediaOverlay(card,"failed")},arm=()=>{clearTimeout(timer);if(video.dataset.near==="false")return;feedMediaOverlay(card,"loading");timer=setTimeout(()=>{if(video.readyState<2||!video.videoWidth)fail()},10000)};video.addEventListener("loadstart",arm);video.addEventListener("loadeddata",clear);video.addEventListener("canplay",clear);video.addEventListener("playing",clear);video.addEventListener("error",fail);video.addEventListener("stalled",()=>{if(video.dataset.near!=="false")arm()});if(video.getAttribute("src"))arm()}
function guardFeedFrame(card,frame){if(frame.dataset.feedGuard)return;frame.dataset.feedGuard="1";let timer=0;const clear=()=>{clearTimeout(timer);frame.dataset.frameReady="1";card.classList.remove("feed-media-failed");card.querySelector(".feed-media-state")?.remove()},arm=()=>{clearTimeout(timer);frame.dataset.frameReady="";if(!frame.getAttribute("src")||frame.src==="about:blank")return;feedMediaOverlay(card,"loading");timer=setTimeout(()=>{if(!frame.dataset.frameReady&&frame.src!=="about:blank")feedMediaOverlay(card,"failed")},12000)};frame.addEventListener("load",()=>{if(frame.src!=="about:blank")clear()});new MutationObserver(arm).observe(frame,{attributes:true,attributeFilter:["src"]});arm()}
function guardFeedMedia(root=document){const cards=root.matches?.(".video-card")?[root]:[...root.querySelectorAll?.(".video-card")||[]];cards.forEach(card=>{const video=card.querySelector("video"),frame=card.querySelector("iframe");if(video)guardFeedVideo(card,video);if(frame)guardFeedFrame(card,frame)})}
const feedMediaGuardObserver=new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1)guardFeedMedia(node.matches?.(".video-card")?node.parentElement:node)})));feedMediaGuardObserver.observe($("#videoFeed"),{childList:true,subtree:true});guardFeedMedia($("#videoFeed"));
$("#videoFeed").addEventListener("click",event=>{const retry=event.target.closest("[data-feed-media-retry]"),open=event.target.closest("[data-feed-media-open]");if(!retry&&!open)return;event.preventDefault();event.stopPropagation();const card=event.target.closest(".video-card");if(open){const url=safeUrl(card?.dataset.url);if(url)window.open(url,"_blank","noopener");return}const video=card?.querySelector("video"),frame=card?.querySelector("iframe");card?.classList.remove("feed-media-failed");feedMediaOverlay(card,"loading");if(video){const src=video.dataset.src||card.dataset.url;video.removeAttribute("src");video.load();setTimeout(()=>{video.src=src;video.load();video.muted=true;video.play().catch(()=>{})},60)}else if(frame){const id=youtubeId(card?.dataset.url),src=frame.dataset.src||(id?"https://www.youtube-nocookie.com/embed/"+encodeURIComponent(id)+"?playsinline=1&rel=0":safeUrl(card?.dataset.url));frame.dataset.frameReady="";frame.src="about:blank";setTimeout(()=>frame.src=src,60)}},true);
